    if not c:
        return

    cycle = c['cycle']
    phase = step_count % (2 * cycle)
    overlap = c.get('overlap', 20)
    speed = c.get('speed', 5.0)
    torque = c.get('torque', 250.0)
    joints = c['joints']
    p_torso = c['p_torso']
    p_arm = c['p_arm']

    if phase < cycle:
        # Activate top leg pad and apply motor to its joint
        for p in p_torso:
            sandbox.set_pad_active(p, True)
        if phase > overlap:
            for p in p_arm:
                sandbox.set_pad_active(p, False)
        else:
            for p in p_arm:
                sandbox.set_pad_active(p, True)
        # Apply motor to the first joint (top leg) with positive speed
        sandbox.set_motor(joints[0], speed, torque)
    else:
        # Activate bottom leg pad and apply motor to its joint
        for p in p_arm:
            sandbox.set_pad_active(p, True)
        if (phase - cycle) > overlap:
            for p in p_torso:
                sandbox.set_pad_active(p, False)
        else:
            for p in p_torso:
                sandbox.set_pad_active(p, True)
        # Apply motor to the second joint (bottom leg) with positive speed
        sandbox.set_motor(joints[1], speed, torque)

